package p;
import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import javax.persistence.*;
@Target({ ElementType.FIELD }) @Retention(RetentionPolicy.RUNTIME) @Documented @interface Cloneable {}
@Entity class PerfTest { @Id Long id; @Cloneable @Column(name = "test_name") String testName; }

package p;
import java.lang.annotation.*;
import javax.persistence.*;
/** a marker */ @java.lang.annotation.Retention(RetentionPolicy.RUNTIME) @interface Audited2 {}
@Entity class Doc { @Id Long id; @Audited2 String body; }

package p;
import java.lang.annotation.*;
import javax.persistence.*;
import org.hibernate.annotations.AttributeBinderType;
@Retention(RetentionPolicy.RUNTIME) @AttributeBinderType(binder = TrackedBinder.class) @interface Tracked {}
@Entity class Doc { @Id Long id; @Tracked String body; }

package p;
import java.lang.annotation.*;
import javax.persistence.*;
@Retention(RetentionPolicy.RUNTIME) @interface Cloneable {}
@Entity class PerfTest { @Id Long id; @Cloneable String testName; }
class Wiring implements org.hibernate.integrator.spi.Integrator {}

package p;
import javax.persistence.*;
import com.lib.Marker;
@Entity class Doc { @Id Long id; @Marker String body; }

package p;
import java.lang.annotation.*;
import com.lib.*;
import javax.persistence.*;
@Target(ElementType.FIELD) @interface Flag {}
@Entity class Doc { @Id Long id; @Flag String body; }
